lesson.code:
greet <- function(name) {
  print(paste("Hello,", name))
}
greet("Ana")
greet("Ben")

square <- function(x) {
  x * x
}
print(square(4))
result <- square(3) + 1
print(result)

sign_of <- function(x) {
  if (x < 0) {
    return("negative")
  }
  "not negative"
}
print(sign_of(-2))
print(sign_of(5))

power <- function(base, exp = 2) {
  base ^ exp
}
print(power(5))
print(power(2, 3))
print(power(exp = 3, base = 10))

to_celsius <- function(f) {
  (f - 32) * 5 / 9
}
print(to_celsius(212))
print(to_celsius(c(32, 50, 212)))

